function palindromicSentence(s) {
  let l = 0,
  r = s.length - 1;
  while (l < r) {
    if (!/[a-zA-Z]/.test(s[l])) {
      l++;
    } else if (!/[a-zA-Z]/.test(s[r])) {
      r--;
    } else {
      if (s[l].toLowerCase() !== s[r].toLowerCase()) {
        return false;
      }
      l++;
      r--;
    }
  }
  return true;
}

